const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $('KL Tasks').all().map((i) => i.json);
const now = Date.now(), H = 864e5;
const recent = rows.filter((r) => r.updatedAt && now - new Date(r.updatedAt).getTime() < H && r.status !== 'todo' && r.status !== 'running');
const passed = recent.filter((r) => r.status === 'review' || r.status === 'done');
const failed = recent.filter((r) => r.status === 'rejected');
const todo = rows.filter((r) => r.status === 'todo').length;
const running = rows.filter((r) => r.status === 'running').length;
const doneAll = rows.filter((r) => r.status === 'review' || r.status === 'done').length;
const short = (t) => String(t).replace(/^\(Max[^)]*\)\s*/, '').replace(/^\(Council[^)]*\)\s*ROAST ROOM for /, 'Council: ').slice(0, 80);
const verdict = (r) => { const m = /VERDICT:\s*([^\n]+)/.exec(r.output_summary || ''); return m ? ' -> ' + m[1].slice(0, 70) : ''; };
let commits = []; try { commits = $('GitHub Commits').all().map((i) => i.json).filter((c) => c && c.commit).map((c) => c.commit.message.split('\n')[0].slice(0, 70)); } catch (e) { commits = []; }
let siteOk = false; try { const s = $('Site Check').first().json; siteOk = (s.statusCode || 0) === 200; } catch (e) { siteOk = false; }
const time = $now.setZone('Asia/Kolkata').toFormat('dd LLL');
const by = {};
for (const r of recent) { const a = r.owner_agent || 'Kalpa'; by[a] = by[a] || { ok: 0, redo: 0 }; if (r.status === 'rejected') by[a].redo++; else by[a].ok++; }
const team = Object.entries(by).sort((a, b) => (b[1].ok + b[1].redo) - (a[1].ok + a[1].redo));
const L = [];
L.push('<b>Kalpa Labs daily update, ' + esc(time) + '</b>');
L.push('Revenue so far: Rs 0 (no paying customers yet)');
L.push('Website: ' + (siteOk ? 'up' : 'NOT answering'));
L.push('');
L.push('<b>Team</b>: 300 agents (72 on n8n free models: 64 council advisors + 8 competitor watchers; 101 automatic code; 112 Claude build agents). Models: Nemotron Super (OpenRouter), Nemotron (NVIDIA), Qwen + gpt-oss (Groq), Kalpa Router backup.');
L.push('<b>Agents who worked today</b>: ' + team.length + (running ? ' (' + running + ' working right now)' : ''));
for (const [a, c] of team.slice(0, 12)) L.push('  ' + esc(a) + ': ' + c.ok + ' done' + (c.redo ? ', ' + c.redo + ' sent back' : ''));
L.push('');
L.push('<b>Jobs today</b>: ' + passed.length + ' done, ' + failed.length + ' sent back, ' + todo + ' in queue, ' + doneAll + ' done in total');
const councils = passed.filter((r) => r.owner_agent === 'Council');
for (const r of councils.slice(0, 8)) L.push('* ' + esc(short(r.title).slice(0, 40)) + esc(verdict(r)));
for (const r of passed.filter((r) => r.owner_agent !== 'Council').slice(0, 8)) L.push('+ ' + esc(short(r.title)));
L.push('');
L.push('<b>Code today</b>: ' + commits.length + ' change' + (commits.length === 1 ? '' : 's'));
for (const c of commits.slice(0, 6)) L.push('- ' + esc(c));
return [{ json: { text: L.join('\n').slice(0, 3900) } }];
